import numpy as np
from scipy import ndimage
F=np.load('source_pixels.npz')['rgb'].astype(float)
for agg in ['median','min','max']:
 if agg=='median': B=np.median(F,axis=0)
 elif agg=='min': B=F.min(0)
 else: B=F.max(0)
 print('\\nAGG',agg)
 for t in [0,1,5,8,10,12,15,20,25,30,35,40,44,50,95]:
  d=np.abs(F[t]-B).max(2)
  m=d>20
  lab,n=ndimage.label(m)
  comps=[]
  for i in range(1,n+1):
   ys,xs=np.where(lab==i)
   if len(xs)>10: comps.append((len(xs),int(xs.min()),int(ys.min()),int(xs.max()),int(ys.max())))
  print(t,sorted(comps,reverse=True)[:8])
